// El webhook de n8n expone el body en $json.body (v1) o directo en $json (v2).
// Este nodo normaliza ambos casos y limpia los valores.
const raw = $input.first().json.body ?? $input.first().json;

return [{
  json: {
    restaurant_name: String(raw.restaurant_name ?? '').trim(),
    owner_name:      String(raw.owner_name      ?? '').trim(),
    email:           String(raw.email           ?? '').trim().toLowerCase(),
    whatsapp:        String(raw.whatsapp        ?? '').trim(),
    city:            String(raw.city            ?? '').trim(),
    restaurant_type: String(raw.restaurant_type ?? '').trim(),
    number_of_tables: Number(raw.number_of_tables) || 0,
    plan_interest:   String(raw.plan_interest   ?? 'Starter').trim(),
    message:         String(raw.message         ?? '').trim(),
    submitted_at:    new Date().toISOString()
  }
}];

const lead = $input.first().json;
const required = ['restaurant_name', 'owner_name', 'email', 'whatsapp', 'plan_interest'];
const missing  = required.filter(f => !lead[f]);

if (missing.length > 0) {
  throw new Error(`Campos requeridos faltantes: ${missing.join(', ')}`);
}

if (!lead.email.includes('@') || !lead.email.includes('.')) {
  throw new Error('Formato de email inválido.');
}

if (!['Starter', 'Pro', 'Enterprise'].includes(lead.plan_interest)) {
  throw new Error(`plan_interest inválido: ${lead.plan_interest}`);
}

return [$input.first()];

const lead = $input.first().json;

// Clasificación sin IA — heurística por tamaño y plan de interés.
// En Fase 3 reemplazar por llamada a OpenAI con prompts/agents/agente-comercial.md
let lead_score       = 'low';
let recommended_plan = lead.plan_interest;
let next_action      = 'send_info';

if (lead.plan_interest === 'Enterprise' || lead.number_of_tables > 40) {
  lead_score  = 'high';
  next_action = 'schedule_call';
} else if (lead.plan_interest === 'Pro' || lead.number_of_tables > 15) {
  lead_score  = 'medium';
  next_action = 'schedule_demo';
}

return [{
  json: { ...lead, lead_score, recommended_plan, next_action }
}];
